 if(!strcmp(c->operation,"inspect")){for(int i=0;i<5;i++)if(roles[i].widget)emit(record("inspect",&roles[i]));return TRUE;}
 if(!strcmp(c->operation,"create-family")){if(roles[0].widget)return FALSE;window_new(0,'A',NULL,FALSE);window_new(2,'C',NULL,FALSE);window_new(1,'B',GTK_WINDOW(roles[0].widget),TRUE);return TRUE;}
