int main(int argc,char**argv){if(argc==2&&!strcmp(argv[1],"--describe")){puts("{\"schema\":1,\"toolkit\":\"GTK4\",\"nativeQualification\":false,\"commands\":\"SEQ command [A|C]\"}");return 0;}if(argc==3&&!strcmp(argv[1],"--validate-command")){struct command c;return parse_command(argv[2],&c)?0:6;}if(argc!=2||strcmp(argv[1],"--run")||!private_environment()){fputs("private Wayland QA environment required\n",stderr);return 2;}gtk_init();family=gtk_window_group_new();independent=gtk_window_group_new();loop=g_main_loop_new(NULL,FALSE);int flags=fcntl(STDIN_FILENO,F_GETFL);if(flags<0||fcntl(STDIN_FILENO,F_SETFL,flags|O_NONBLOCK)<0)return 2;g_unix_fd_add(STDIN_FILENO,G_IO_IN|G_IO_HUP|G_IO_ERR,stdin_ready,NULL);emit(record("ready",NULL));g_main_loop_run(loop);g_main_loop_unref(loop);g_object_unref(family);g_object_unref(independent);return exit_code;}
